	float	Dot3(float x0, float x1, float x2, float* vec3)
	{
		return x0 * vec3[0] + x1 * vec3[1] + x2 * vec3[2];
	}

	void	Mat33MulV(float* z0, float* z1, float* z2, float x, float y, float z, float* mat)
	{
		*z0 = Dot3(x, y, z, &mat[0]);
		*z1 = Dot3(x, y, z, &mat[3]);
		*z2 = Dot3(x, y, z, &mat[6]);
	}

